import Foundation

/// 界面文案（中/英）—— **构建时从 `D:\_build\i18n_map.py` 生成，别手改**。
///
/// 🚨 安卓那边同一份表生成 `res/values{,-en}/strings.xml`。
///    两端共用一个配置点，改文案只改 i18n_map.py 再跑一次生成脚本。
///    以前 iOS 的文案是手写的，跟安卓靠注释「一一对应」维持 ——
///    结果「结构化转写/逐字转录」这种被他否掉的措辞在 iOS 留了一整天。
///
/// 🚨 语言由 `Bundle.main.preferredLocalizations` 决定 ——
///    那是**系统给的解析结果**（用户偏好 ∩ App 声明支持的语言），
///    不是我自己解析 Locale。自己解析会跟系统的选择打架。
///    配套：project.yml 里必须声明 CFBundleLocalizations，
///    否则系统不知道这个 App 支持英文，永远返回开发语言。
enum L {
    /// 当前界面语言代码。
    ///
    /// 🚨🚨 **必须读 `Lang.effective`，不能读 `preferredLocalizations`**
    ///    （2026-09-05 修，Kevin 实机报「选 English 后整个界面还是中文」）：
    ///    读系统语言的话，App 内那个「界面语言」设置项**根本没人读**。
    /// 🚨🚨 **必须是计算属性，不能是 `static let`** ——
    ///    `static let` 每进程只算一次，切完语言要等重启才变。
    ///    🚨 这两条**曾经被生成器打回去过**：模板里写死成 `static let`，
    ///       一跑生成就把修复覆盖掉。现在模板里就是对的，别再改回去。
    private static var code: String {
        switch Lang.effective {
        case Lang.en: return "en"
        case Lang.hant: return "zh-Hant"
        // 🚨🚨 **新加的语言必须各回各的码**（2026-09-06）。
        //    原来它们全掉进 `default` -> "zh-Hans" ——
        //    **App 内部认为用户在用简体中文**。
        //    表面症状只是 slogan 出中文（`isEn` 是唯一的消费者），
        //    但根子是这里：下一个用 `isEn`/`isHant` 的人会再中一次。
        case Lang.ja: return "ja"
        case Lang.de: return "de"
        case Lang.es: return "es"
        case Lang.ar: return "ar"
        default: return "zh-Hans"
        }
    }

    /// 当前界面是不是英文。
    static var isEn: Bool { !code.hasPrefix("zh") }

    /// 当前界面是不是繁体中文。
    /// 🚨 判据用 `zh-Hant` 前缀，**不要枚举 zh-TW/zh-HK/zh-MO** ——
    ///    系统在 App 声明支持 zh-Hant 时返回的就是 zh-Hant，
    ///    枚举地区码会漏掉它，然后静默掉回简体。
    static var isHant: Bool { code.hasPrefix("zh-Hant") }

    /// 按当前界面语言取一条文案。
    ///
    /// 🚨🚨 **原来是三个位置参数** `s(zh, en, hant)` —— 结构上装不下第四门。
    ///    Kevin 2026-09-06 两次点名要日/德/西/阿，译文早就跑完了，
    ///    **没地方放**。这不是漏了一步，是文案系统装不下。
    ///
    /// 🚨 回落顺序：**要的那门 → en → zh**。
    ///    日德西阿的用户看英文能懂、看中文看不懂 ——
    ///    回落要落到「更多人能读」的那一门。
    ///    （三参那版里非英非繁一律落中文，那对日语用户是最差的一档。）
    private static func s(_ m: [String: String]) -> String {
        if let v = m[Lang.effective], !v.isEmpty { return v }
        if let v = m[Lang.en], !v.isEmpty { return v }
        return m[Lang.zh] ?? ""
    }

    static var del_acct_entry: String { s(["zh": "删除账号", "en": "Delete account", "hant": "刪除帳號", "ja": "アカウント削除", "de": "Konto löschen", "es": "Eliminar cuenta", "ar": "حذف الحساب"]) }
    static var del_acct_title: String { s(["zh": "删除账号", "en": "Delete account", "hant": "刪除帳號", "ja": "アカウント削除", "de": "Konto löschen", "es": "Eliminar cuenta", "ar": "حذف الحساب"]) }
