    static var about_tagline: String { s(["zh": "让世界听懂你", "en": "No Language In Between", "hant": "讓世界聽懂你", "ja": "言葉の壁をなくす", "de": "Keine Sprache dazwischen", "es": "Sin idiomas intermedios", "ar": "لا لغة بيننا"]) }
    static var about_body1: String { s(["zh": "Transless 首先是一个语音输入法——按住说话，出来的就是能直接发送的文字：把你说的话整理通顺，或者直接变成地道的外语。", "en": "Transless is first of all a voice keyboard: hold to speak and you get text you can send right away — your own words tidied up, or turned straight into natural, idiomatic wording in another language.", "hant": "Transless 首先是一個語音輸入法——按住說話，出來的就是能直接發送的文字：把你說的話整理通順，或者直接變成地道的外語。", "ja": "Translessはまず音声入力キーボードです——押しながら話すと、そのまま送信できる文字が出ます。自分の言葉を整えたり、別の言語の自然で慣用的な表現に直接変換したりできます。", "de": "Transless ist zuerst eine Sprach-Tastatur: Halte zum Sprechen und du bekommst Text, den du direkt senden kannst — deine eigenen Worte aufgeräumt oder direkt in natürliche, idiomatische Formulierungen in einer anderen Sprache umgewandelt.", "es": "Transless es ante todo un teclado de voz: mantén presionado para hablar y obtén texto que puedes enviar de inmediato — tus propias palabras ordenadas, o convertidas directamente en una redacción natural e idiomática en otro idioma.", "ar": "‎Transless‎ هو أولاً لوحة مفاتيح صوتية: اضغط مع الاستمرار للتحدث وستحصل على نص يمكنك إرساله فورًا — كلماتك مرتبة، أو محوّلة مباشرة إلى صياغة طبيعية وسليمة بلغة أخرى."]) }
    static var about_body2: String { s(["zh": "它也不止是输入法：面对面翻译帮你当面跟外国人对话，随便说点啥不用切出输入法就能查一句话，单词本把你用过的表达收进复习流程——说得越多，你自己脱口而出的也越多。", "en": "It is more than a keyboard: face-to-face translation for talking to someone in person, quick translation without leaving the keyboard, and a word book that turns what you have used into review — the more you speak, the more comes out on its own.", "hant": "它也不止是輸入法：面對面翻譯幫你當面跟外國人對話，隨便說點啥不用切出輸入法就能查一句話，單詞本把你用過的表達收進複習流程——說得越多，你自己脫口而出的也越多。", "ja": "キーボードだけではありません。対面翻訳で直接外国人と話せ、キーボードを離れずに一言を調べられるクイック翻訳、使った表現を復習に取り込む単語帳もあります。話せば話すほど、自然に言葉が出てきます。", "de": "Es ist mehr als eine Tastatur: Für Gespräche von Angesicht zu Angesicht gibt es die Übersetzung für direkte Unterhaltungen, für schnelle Übersetzungen musst du die Tastatur nicht verlassen, und ein Wortbuch macht aus dem, was du benutzt hast, eine Wiederholung – je mehr du sprichst, desto mehr kommt von selbst heraus.", "es": "Es más que un teclado: traducción cara a cara para conversar en persona, traducción rápida sin salir del teclado, y un cuaderno de palabras que convierte lo que usas en repaso — cuanto más hablas, más sale por sí solo.", "ar": "إنه أكثر من لوحة مفاتيح: ترجمة وجهاً لوجه للتحدث مع شخص ما، وترجمة سريعة دون مغادرة لوحة المفاتيح، ودفتر كلمات يحوّل ما استخدمته إلى مراجعة — كلما تحدثت أكثر، خرج منك أكثر تلقائياً."]) }
    static var about_langs_title: String { s(["zh": "支持语言", "en": "Languages", "hant": "支援語言", "ja": "対応言語", "de": "Sprachen", "es": "Idiomas", "ar": "اللغات"]) }
