    static var hs_sub: String { s(["zh": "你说过的话只留在这台设备上。打开后可以在你的其他设备上看到，但内容会存在我们的服务器上。", "en": "What you say stays on this device only. Turn this on to see it on your other devices — but the content will be stored on our servers.", "hant": "你說過的話只留在這臺設備上。打開後可以在你的其他設備上看到，但內容會存在我們的伺服器上。", "ja": "発言はこの端末にのみ保存されます。オンにすると他の端末でも表示できますが、内容は当社のサーバーに保存されます。", "de": "Was du sagst, bleibt nur auf diesem Gerät. Schalte dies ein, um es auf deinen anderen Geräten zu sehen – aber der Inhalt wird auf unseren Servern gespeichert.", "es": "Lo que dices se queda solo en este dispositivo. Actívalo para verlo en tus otros dispositivos, pero el contenido se almacenará en nuestros servidores.", "ar": "ما تقوله يبقى على هذا الجهاز فقط. شغّل هذا لتراه على أجهزتك الأخرى — لكن سيتم تخزين المحتوى على خوادمنا."]) }
    static var hs_ask_title: String { s(["zh": "把说话记录同步到云端？", "en": "Sync what you say to the cloud?", "hant": "把說話記錄同步到雲端？", "ja": "発言をクラウドに同期しますか？", "de": "Gesprochenes mit der Cloud synchronisieren?", "es": "¿Sincronizar lo que dices con la nube?", "ar": "مزامنة ما تقوله إلى السحابة؟"]) }
    static var hs_ask_1: String { s(["zh": "· 这些内容会存在我们的服务器上，我们没有加密，能看到内容。", "en": "· This content is stored on our servers. It is not encrypted, and we can read it.", "hant": "· 這些內容會存在我們的伺服器上，我們沒有加密，能看到內容。", "ja": "・この内容は当社のサーバーに保存されます。暗号化されておらず、当社が内容を確認できます。", "de": "· Dieser Inhalt wird auf unseren Servern gespeichert. Er ist nicht verschlüsselt, und wir können ihn lesen.", "es": "· Este contenido se almacena en nuestros servidores. No está cifrado y podemos leerlo.", "ar": "· هذا المحتوى مخزَّن على خوادمنا. وهو غير مشفَّر، ويمكننا قراءته."]) }
    static var hs_ask_2: String { s(["zh": "· 这些内容在写入前会先经过我们位于中国大陆的服务器处理，最终存储在新加坡的服务器上。", "en": "· Before it is stored, this content is processed on our servers in mainland China, and is then stored on servers in Singapore.", "hant": "· 這些內容在寫入前會先經過我們位於中國大陸的伺服器處理，最終存儲在新加坡的伺服器上。", "ja": "・この内容は保存前に中国本土のサーバーで処理され、最終的にシンガポールのサーバーに保存されます。", "de": "· Bevor er gespeichert wird, wird dieser Inhalt auf unseren Servern in Festlandchina verarbeitet und dann auf Servern in Singapur gespeichert.", "es": "· Antes de almacenarse, este contenido se procesa en nuestros servidores en China continental y luego se guarda en servidores en Singapur.", "ar": "· قبل تخزينه، تتم معالجة هذا المحتوى على خوادمنا في البر الرئيسي للصين، ثم يُخزَّن على خوادم في سنغافورة."]) }
